assert not m.strokes and [(r['rect'],r['radius']) for r in m.rounded]==[((0,0,287,40),O['SEL_RADIUS'])]
assert [l['text'] for l in m.letters]==['OK'] and m.lcd_colors()==LCD_COLORS
