assert m.nodes[slide]['value']==1 and not m.clicks
assert m.call(O['KEY_BACK_BTN'])==11 and field()==4 and m.call(O['KEY_BACK_BTN'])==11 and field()==3
assert not any(c[0] in ('media_key','stock_input') for c in m.calls)
