assert m.call(gap=500)==11 and not m.slides and m.get(w+O['SLIDE_ANIMATOR'])==0 and m.get(w+O['SLIDE_INDEX'])==1 and m.get(w+O['SLIDE_OFFSET'])==0
assert 'widget_animator_scroll_create' not in [c[0] for c in m.calls]
