ov.save(65); assert ov.config=={'VOLUME':'20','BT_VOLUME':'65'}
assert ov.output(0)==20; ov.save(13)
assert ov.output(1)==65 and ov.output(1)==65 and ov.output(2)==13
assert ov.output(0)==13 and ov.output(1)==65; passed()
