    m.advance(ms,clear=False)
    if m.fresh: m.word(ps['wheel_frame_at'],m.now)  # as its frames stamp it
    m.call(address=sleep_hook,args=(0x1234,0,0,0),gap=0,clear=False,debounce=True)
