assert t.files['/tmp/q2-scan.log']==b'500 91000 /mnt/mmc/500.opus\n'  # this demo's first line starts the file
t.STATM=b'30000 23000 1200 1 0 25000 0\n'
for i in range(501,1001): t.album_artist(f'/mnt/mmc/{i}.opus')
